20.code:
function hisobot(ballar) {
  if (!Array.isArray(ballar) || ballar.length === 0) return null;
  let summa = 0, otganlar = 0;
  for (const ball of ballar) {
    if (!Number.isInteger(ball) || ball < 0 || ball > 100) return null;
    summa += ball;
    if (ball >= 60) otganlar++;
  }
  return { ortacha: summa / ballar.length, otganlar };
}
const natija = hisobot([40, 60, 80]);
if (natija === null) console.log("Yaroqsiz kirish");
else console.log("Hisobot:", natija.ortacha, natija.otganlar);
